// Verified 2026 additions missing from the bundled Book1.xlsx snapshot.
// Keep these separate from the generated workbook export so future workbook
// regeneration cannot silently discard externally verified additions.
const SUPP2026_POSITIONS = Object.freeze([1, 2, 3, 4, 5]);

function supp2026Character({
  id, name, attributes, cost, baseHp, basePow, hp, pow, rarity, region,
  skillTurn, skill, skillName, skillCategory, roleTags, notes, maxLevel, limitBreak,
}) {
  const resolvedMaxLevel = maxLevel ?? (rarity === "N" ? 72 : rarity === "R" ? 100 : rarity === "CR" ? 132 : 237);
  const resolvedLimitBreak = limitBreak ?? (rarity === "N" ? 4 : rarity === "R" ? 5 : rarity === "CR" ? 6 : 7);
  return Object.freeze({
    source: Object.freeze({ sheet: "手動補完2026", row: id }),
    id, name, attributes: Object.freeze(attributes), cost, hp, pow, baseHp, basePow,
    maxLevel: resolvedMaxLevel, limitBreak: resolvedLimitBreak, rarity, region, owned: true, pvpTier: "normal",
    allowedPositions: SUPP2026_POSITIONS, preferredPositions: SUPP2026_POSITIONS,
    positionRule: "free", skillTurn, maxUses: 2,
    skill: Object.freeze({
      hits: 1, amount: 0, target: "enemy_one", targetCount: 1, duration: 1,
      priority: "normal", conditions: Object.freeze([]), effects: Object.freeze([]),
      ...skill,
      conditions: Object.freeze((skill.conditions ?? []).map((entry) => Object.freeze(entry))),
      effects: Object.freeze((skill.effects ?? []).map((entry) => Object.freeze(entry))),
    }),
    skillName, skillCategory, roleTags: Object.freeze(roleTags), notes,
  });
}

const ally = (attribute) => Object.freeze({ type: "ally_attribute", attribute });
const enemy = (attribute) => Object.freeze({ type: "enemy_attribute", attribute });
const effect = (attribute) => Object.freeze({ attribute });

